import pytest


def test_verify_file_rejects_non_yaml_extension(tmp_path):
    import ansible.plugins.inventory.auto as auto
    p = tmp_path / 'inv.txt'
    p.write_text('plugin: foo')
    plugin = auto.InventoryModule()
    assert plugin.verify_file(str(p)) is False


def test_verify_file_accepts_existing_yaml_files(tmp_path):
    import ansible.plugins.inventory.auto as auto
    plugin = auto.InventoryModule()
    for name in ('inv.yml', 'inv.yaml'):
        p = tmp_path / name
        p.write_text('plugin: foo')
        assert plugin.verify_file(str(p)) is True


