def test_parse_delegates_and_updates_cache(monkeypatch):
    import ansible.plugins.inventory.auto as auto

    calls = {}

    class Loader(object):
        def load_from_file(self, path, cache=True):
            calls['load_cache'] = cache
            return {'plugin': 'fake'}

    class FakePlugin(object):
        def verify_file(self, path):
            calls['verified'] = path
            return True

        def parse(self, inventory, loader, path, cache=True):
            calls['parse'] = (inventory, loader, path, cache)

        def update_cache_if_changed(self):
            calls['updated'] = True

    requested = []

    def fake_get(name):
        requested.append(name)
        return FakePlugin()

    monkeypatch.setattr(auto.inventory_loader, 'get', fake_get)
    inv = object()
    loader = Loader()
    plugin = auto.InventoryModule()
    plugin.parse(inv, loader, 'conf.yml', cache=False)
    assert requested == ['fake']
    assert calls['load_cache'] is False
    assert calls['verified'] == 'conf.yml'
    assert calls['parse'] == (inv, loader, 'conf.yml', False)
    assert calls['updated'] is True


def test_parse_without_update_cache_method(monkeypatch):
    import ansible.plugins.inventory.auto as auto

    calls = {}

    class Loader(object):
        def load_from_file(self, path, cache=True):
            return {'plugin': 'fake'}

    class FakePlugin(object):
        def verify_file(self, path):
            return True

        def parse(self, inventory, loader, path, cache=True):
            calls['parsed'] = cache

    monkeypatch.setattr(auto.inventory_loader, 'get', lambda name: FakePlugin())
    plugin = auto.InventoryModule()
    plugin.parse(object(), Loader(), 'conf.yml')
    assert calls['parsed'] is True

