def test_raw_stream_body_only_with_callback():
    from httpie.output.streams import RawStream

    class Msg:
        headers = 'H'
        seen = None

        def iter_body(self, chunk_size):
            Msg.seen = chunk_size
            return iter([b'abc', b'def'])

    got = []
    s = RawStream(msg=Msg(), with_headers=False, on_body_chunk_downloaded=got.append)
    assert s.chunk_size == RawStream.CHUNK_SIZE
    assert list(s) == [b'abc', b'def']
    assert got == [b'abc', b'def']
    assert Msg.seen == RawStream.CHUNK_SIZE

    s2 = RawStream(chunk_size=5, msg=Msg(), with_headers=True)
    assert list(s2) == [b'H', b'\r\n\r\n', b'abc', b'def']
    assert Msg.seen == 5
