def test_data_suppressed_messages():
    from httpie.output.streams import (
        BaseStream, BinarySuppressedError, DataSuppressedError,
        BINARY_SUPPRESSED_NOTICE,
    )
    assert DataSuppressedError.message is None
    assert BinarySuppressedError.message == BINARY_SUPPRESSED_NOTICE
    assert issubclass(BinarySuppressedError, DataSuppressedError)

    class Msg:
        headers = 'H'

    class Stream(BaseStream):
        def iter_body(self):
            yield b'first'
            raise BinarySuppressedError()

    assert list(Stream(msg=Msg(), with_headers=True)) == [
        b'H', b'\r\n\r\n', b'first', b'\n', BINARY_SUPPRESSED_NOTICE]
    assert list(Stream(msg=Msg(), with_headers=False)) == [
