def _make(lines, converter=None, with_headers=True):
    from httpie.output.streams import PrettyStream

    class Env:
        stdout_isatty = False
        stdout_encoding = 'utf8'

    class Msg:
        headers = 'hdr'
        encoding = 'utf8'
        content_type = 'text/plain; charset=utf8'

        def iter_lines(self, chunk_size):
            return iter(lines)

    class Formatting:
        def format_headers(self, h):
            return h.upper()

        def format_body(self, content, mime):
            return '[%s]%s' % (mime, content)

    class Conversion:
        def get_converter(self, mime):
            return converter

    return PrettyStream(conversion=Conversion(), formatting=Formatting(),
                        env=Env(), msg=Msg(), with_headers=with_headers)


