        """Check the name is public style or listed in `__all__`."""
        if s in self.imp:
            for ch in chain(self.doc.keys(), self.const.keys()):
                if ch.startswith(s + '.') and is_public_family(ch):
                    break
            else:
                return False
        all_l = self.imp[self.root[s]]
        if all_l:
            return s == self.root[s] or bool({s, parent(s)} & all_l)
        else:
            return is_public_family(s)

    def __get_const(self, name: str) -> str:
        """Get constants table."""
        const = []
        for c in self.const:
            if self.root[c] == name and self.is_public(c):
                ch = c.removeprefix(name + '.')
                const.append((code(ch), code(self.const[c])))
        if const:
            return table('Constants', 'Type', items=const)
        else:
            return ""

    def __names_cmp(self, s: str) -> tuple[int, str, bool]:
        """Name comparison function."""
        return self.level[s], s.lower(), not s.islower()

    def compile(self) -> str:
        """Compile documentation."""
        self.__find_alias()
        toc = ['**Table of contents:**']
        docs = []
        for name in sorted(self.doc, key=self.__names_cmp):
            if not self.is_public(name):
                continue
            link = name.lower().replace('.', '-')
            doc = self.doc[name].format(name, link)
            if name in self.imp:
                doc += self.__get_const(name)
            if name in self.docstring:
                doc += self.docstring[name]
            elif is_magic(name):
                continue
            else:
                logger.warning(f"Missing documentation for {name}")
            level = name.removeprefix(self.root[name]).count('.')
            toc.append(" " * 4 * level + f"+ [{code(name)}](#{link})")
            docs.append(doc.rstrip())
        if self.toc:
            return '\n'.join(toc) + '\n\n' + "\n\n".join(docs) + '\n'
        return "\n\n".join(docs) + '\n'
"
}

### Role
You are an expert Python software engineer specializing in automated test generation and software quality assurance.

### Task
Given a Python module name and its source code, generate one or more pytest test functions that together provide meaningful coverage of the module's functionality, including its edge cases, branching logic, and key behaviors.

### Input
- `m`: The fully qualified Python module name (e.g., `package.submodule`)
- `code`: The full source code of the module as a string

### Output
A JSON object with the following structure:
```json
{
  "tests": [
    "<pytest test function as a self-contained Python string>",
    ...
  ]
}
```
Each element of `tests` is a complete, self-contained pytest test function as a Python source string. Each test must be independently runnable (i.e., it imports what it needs and does not rely on shared state with other tests).

