import pytest


def test_slurp_success(monkeypatch, tmp_path):
    import base64
    import ansible.modules.slurp as slurp

    data = b'hello\x00world\n\xff'
    f = tmp_path / 'file.bin'
    f.write_bytes(data)

    class Exited(Exception):
        pass

    class FakeModule(object):
        def __init__(self, *args, **kwargs):
            self.params = {'src': str(f)}

        def exit_json(self, **kwargs):
            raise Exited(kwargs)

        def fail_json(self, msg, **kwargs):
            raise AssertionError('unexpected failure: %s' % msg)

    monkeypatch.setattr(slurp, 'AnsibleModule', FakeModule)
    with pytest.raises(Exited) as exc:
        slurp.main()
    result = exc.value.args[0]
    assert result['content'] == base64.b64encode(data)
    assert result['source'] == str(f)
    assert result['encoding'] == 'base64'
