def test_xattr_run_writes_all_attributes(monkeypatch):
    import youtube_dl.postprocessor.xattrpp as xattrpp

    class FakeDL(object):
        def __init__(self):
            self.screen = []
            self.errors = []
            self.warnings = []

        def to_screen(self, msg):
            self.screen.append(msg)

        def report_error(self, msg):
            self.errors.append(msg)

        def report_warning(self, msg):
            self.warnings.append(msg)

    calls = {}

    def fake_write(filename, name, value):
        calls[name] = (filename, value)

    monkeypatch.setattr(xattrpp, 'write_xattr', fake_write)
    dl = FakeDL()
    pp = xattrpp.XAttrMetadataPP(dl)
    info = {
        'filepath': 'f.mp4',
        'webpage_url': 'http://example.com/v',
        'title': 'T',
        'upload_date': '20200131',
        'description': 'D',
        'uploader': 'U',
        'format': 'F',
    }
    result = pp.run(info)
    assert result == ([], info)
    assert len(calls) == 6
    assert calls['user.dublincore.date'] == ('f.mp4', b'2020-01-31')
    assert calls['user.dublincore.title'] == ('f.mp4', b'T')
    assert calls['user.xdg.referrer.url'][1] == b'http://example.com/v'
    assert len(dl.screen) == 1
    assert not dl.errors and not dl.warnings
