def test_list_deprecations():
    import ansible.module_utils.common.parameters as p
    spec = {
        'old': {'removed_in_version': '2.9', 'removed_from_collection': 'ns.col'},
        'dt': {'removed_at_date': '2030-01-01'},
        'sub': {'type': 'dict', 'options': {'inner': {'removed_in_version': '1.0'}}},
        'absent': {'removed_in_version': '3.0'},
    }
    params = {'old': 1, 'dt': 2, 'sub': {'inner': 3}}
    result = p._list_deprecations(spec, params)
    assert len(result) == 3
    assert result[0]['version'] == '2.9'
    assert result[0]['collection_name'] == 'ns.col'
    assert result[0]['msg'].startswith("Param 'old' is deprecated")
    assert result[1]['date'] == '2030-01-01'
    assert result[1]['collection_name'] is None
    assert result[2]['version'] == '1.0'
    assert 'inner' in result[2]['msg']
    assert result[2]['msg'].count(chr(34)) == 2


