def test_validate_argument_values_bool_conversion_and_bad_choices():
    import ansible.module_utils.common.parameters as p
    from ansible.module_utils.errors import ArgumentTypeError
    spec = {'a': {'choices': ['yes', 'no']}}
    errors = p.AnsibleValidationErrorMultiple()
    params = {'a': 'False'}
    p._validate_argument_values(spec, params, errors=errors)
    assert params['a'] == 'no'
    params = {'a': 'True'}
    p._validate_argument_values(spec, params, errors=errors)
    assert params['a'] == 'yes'
    assert len(errors.errors) == 0

    # ambiguous conversion leaves the value and reports an error
    spec = {'a': {'choices': ['a', 'b']}}
    params = {'a': 'False'}
    p._validate_argument_values(spec, params, errors=errors)
    assert len(errors.errors) == 1

    # non-iterable choices
    errors = p.AnsibleValidationErrorMultiple()
    p._validate_argument_values({'a': {'choices': 5}}, {'a': 1}, errors=errors)
    assert isinstance(errors.errors[0], ArgumentTypeError)
    errors = p.AnsibleValidationErrorMultiple()
    p._validate_argument_values({'a': {'choices': 'abc'}}, {'a': 'a'}, options_context=['top'], errors=errors)
    assert isinstance(errors.errors[0], ArgumentTypeError)
