def test_getent_duplicate_keys_become_lists(monkeypatch):
    import ansible.modules.getent as getent
    out = 'root:x:0:0\nroot:y:1:1\nroot:z:2:2\nbob:q:3:3\n'
    res, mod = _run(monkeypatch, {'database': 'group', 'fail_key': True}, rc=0, out=out)
